// Shared computed figures and ledger helpers for ISC 11 Accounts ch04 (Ledger). Every ledger in a slide, note or item
// is generated by acc.mjs ledger()/post() from a journal whose entries balance, with the balance c/d and b/d
// asserted. Imagined firms only. No GST transactions (syllabus note).
import { same, check, sum, inr, rs, mdTable, journal, ledger, post, trialFromLedgers, trading, profitLoss, balanceSheet } from './acc.mjs';

export { same, check, sum, inr, rs, mdTable, journal, ledger, post, trialFromLedgers, trading, profitLoss, balanceSheet };

// ---------------------------------------------------------------- journal with ledger folios
/** Journal with a ledger-folio column. folio = { account: ledger page }. Balance is asserted by journal(). */
export function jrnl(entries, folio = {}) {
  const j = journal(entries);
  const f = (a) => {
    check(folio[a] !== undefined, `no ledger folio for ${a}`);
    return String(folio[a]);
  };
  const rows = [];
  for (const e of entries) {
    e.dr.forEach(([a, m], i) => rows.push([i ? '' : e.date ?? '', `${a} Dr.`, f(a), inr(m), '']));
    for (const [a, m] of e.cr) rows.push(['', `To ${a}`, f(a), '', inr(m)]);
    rows.push(['', `*(${e.note})*`, '', '', '']);
  }
  rows.push(['', '**Total**', '', `**${inr(j.total)}**`, `**${inr(j.total)}**`]);
  const headers = ['Date', 'Particulars', 'L.F.', 'Dr (₹)', 'Cr (₹)'];
  return { headers, rows, md: mdTable(headers, rows), total: j.total };
}

/** Opening balances implied by an opening journal entry: debits are debit balances, credits are credit balances. */
export function openingsFrom(entry) {
  journal([entry]);
  const o = {};
  for (const [a, m] of entry.dr) o[a] = { side: 'dr', amount: m };
  for (const [a, m] of entry.cr) o[a] = { side: 'cr', amount: m };
  return o;
}

// ---------------------------------------------------------------- dated posting
/**
 * Posts dated journal entries to ledger accounts (To/By with the account on the other side, "Sundries" when several)
 * with the journal folio. Returns { [account]: ledger(...) }; balances agree with acc.mjs post().
 */
export function postD(entries, { openings = {}, jf = 1 } = {}) {
  journal(entries);
  const acc = {};
  const get = (k) => (acc[k] ??= { dr: [], cr: [] });
  for (const e of entries) {
    const crName = e.cr.length === 1 ? e.cr[0][0] : 'Sundries';
    const drName = e.dr.length === 1 ? e.dr[0][0] : 'Sundries';
    const p = e.jf ?? jf;
    for (const [a, m] of e.dr) get(a).dr.push([`${e.date} To ${crName} (J.F. ${p})`, m]);
    for (const [a, m] of e.cr) get(a).cr.push([`${e.date} By ${drName} (J.F. ${p})`, m]);
  }
  for (const k of Object.keys(openings)) get(k);
  const out = {};
  for (const [k, v] of Object.entries(acc)) out[k] = ledger({ name: k, opening: openings[k], ...v });
  const plain = post(entries, openings);
  for (const k of Object.keys(plain)) same(out[k].balance, plain[k].balance, `ledger balance of ${k} agrees with post()`);
  for (const k of Object.keys(out)) check(plain[k], `account ${k} missing in post()`);
  return out;
}

/**
 * Ledger account as a table with dated c/d and b/d rows. close = date of the balance c/d, open = date of the balance
 * b/d. Asserts the next period's opening balance equals the closing balance and sits on the opposite side.
 */
export function showL(l, { close, open, openingDate } = {}) {
  const dt = (t) => (/^(To|By) Balance b\/d$/.test(t) ? `${openingDate ? openingDate + " " : ""}${t}` : /^(To|By) Balance c\/d$/.test(t) ? `${close ? close + " " : ""}${t}` : t);
  const rows = [...l.rows.slice(0, -1).map(([dp, da, cp, ca]) => [dt(dp), da, dt(cp), ca]), l.rows[l.rows.length - 1]];
  if (l.balance) {
    check(open !== undefined, `b/d date needed for ${l.name}`);
    rows.push(l.balance > 0 ? [`${open ? open + " " : ""}To Balance b/d`, inr(l.balance), '', ''] : ['', '', `${open ? open + " " : ""}By Balance b/d`, inr(-l.balance)]);
  }
  const headers = [`Dr: ${l.name ?? 'Account'}`, '₹', 'Cr: Particulars', '₹'];
  return { ...l, rows, headers, md: mdTable(headers, rows), side: l.balance >= 0 ? 'debit' : 'credit', bal: Math.abs(l.balance) };
}
/** Markdown of a ledger account with a bold heading line. */
export const acct = (l, opts) => `**${l.name}**\n\n${showL(l, opts).md}`;

// ---------------------------------------------------------------- closing entries
/**
 * Closing journal entries at the end of a period. Each nominal account goes to the Trading or Profit and Loss Account
 * in its own entry (so the ledger of each shows its own line). tradingDr: debit-balance accounts closed to Trading
 * (opening stock, purchases, sales return, direct expenses); tradingCr: credit-balance accounts and closing stock;
 * plDr: indirect expenses and losses; plCr: incomes. Gross profit, net profit and the drawings transfer follow.
 * Asserts the profit figures against acc.mjs trading() and profitLoss().
 */
export function closingEntries({ date, tradingDr, tradingCr, plDr, plCr, capital = 'Capital A/c', drawings }) {
  const E = [];
  const nm = (a) => a.replace(/ A\/c$/, '');
  for (const [a, m] of tradingDr) E.push({ date, dr: [['Trading A/c', m]], cr: [[a, m]], note: `Being ${nm(a)} transferred to Trading Account` });
  for (const [a, m] of tradingCr) E.push({ date, dr: [[a, m]], cr: [['Trading A/c', m]], note: `Being ${nm(a)} transferred to Trading Account` });
  const t = trading({ dr: tradingDr.map(([a, m]) => [`To ${a}`, m]), cr: tradingCr.map(([a, m]) => [`By ${a}`, m]) });
  const gp = t.gp;
  if (gp > 0) E.push({ date, dr: [['Trading A/c', gp]], cr: [['Profit and Loss A/c', gp]], note: 'Being gross profit transferred to Profit and Loss Account' });
  else if (gp < 0) E.push({ date, dr: [['Profit and Loss A/c', -gp]], cr: [['Trading A/c', -gp]], note: 'Being gross loss transferred to Profit and Loss Account' });
  for (const [a, m] of plDr) E.push({ date, dr: [['Profit and Loss A/c', m]], cr: [[a, m]], note: `Being ${nm(a)} transferred to Profit and Loss Account` });
  for (const [a, m] of plCr) E.push({ date, dr: [[a, m]], cr: [['Profit and Loss A/c', m]], note: `Being ${nm(a)} transferred to Profit and Loss Account` });
  const p = profitLoss({ dr: [...plDr.map(([a, m]) => [`To ${a}`, m]), ...(gp < 0 ? [['To Gross Loss', -gp]] : [])], cr: [...plCr.map(([a, m]) => [`By ${a}`, m]), ...(gp > 0 ? [['By Gross Profit', gp]] : [])] });
  const np = p.np;
  if (np > 0) E.push({ date, dr: [['Profit and Loss A/c', np]], cr: [[capital, np]], note: 'Being net profit transferred to Capital Account' });
  else if (np < 0) E.push({ date, dr: [[capital, -np]], cr: [['Profit and Loss A/c', -np]], note: 'Being net loss transferred to Capital Account' });
  if (drawings) E.push({ date, dr: [[capital, drawings[1]]], cr: [[drawings[0], drawings[1]]], note: 'Being drawings transferred to Capital Account' });
  journal(E);
  return { entries: E, gp, np, trading: t, pl: p };
}
/** Asserts every nominal account (and Trading, Profit and Loss) closes with no balance after the closing entries. */
export function assertClosed(ledgers, names) {
  for (const n of names) {
    check(ledgers[n], `account ${n} not found`);
    same(ledgers[n].balance, 0, `${n} closes with no balance`);
  }
}

// ================================================================ Case A: Parvati Coir Works (year 2027-28)
export const PC = {
  open: { cash: 85000, stock: 140000, mach: 300000, venkat: 65000 },
  purchases: 240000, cashSales: 310000, paidVenkat: 250000, creditSale: 180000, wages: 48000, rent: 30000, recdIsmail: 120000,
  furn: 75000, furnCash: 30000, carriage: 8000, drawings: 36000, interest: 12000, purchRet: 15000, salesRet: 10000,
  closingStock: 110000, wagesDue: 4000, rentPrepaid: 5000, interestAccrued: 3000, depPct: 10,
};
PC.cap = PC.open.cash + PC.open.stock + PC.open.mach - PC.open.venkat;
same(PC.cap, 460000, 'PC capital');
export const PC_FOLIO = {
  'Cash A/c': 1, 'Stock A/c': 2, 'Machinery A/c': 3, 'Venkat Fibre Co. A/c': 4, 'Capital A/c': 5, 'Purchases A/c': 6, 'Sales A/c': 7,
  'Ismail and Sons A/c': 8, 'Wages A/c': 9, 'Rent A/c': 10, 'Carriage Inwards A/c': 11, 'Furniture A/c': 12, 'Drawings A/c': 13,
  'Interest Received A/c': 14, 'Purchases Return A/c': 15, 'Sales Return A/c': 16,
};
export const PC_OPENING = {
  date: '1 Apr 2027',
  dr: [['Cash A/c', PC.open.cash], ['Stock A/c', PC.open.stock], ['Machinery A/c', PC.open.mach]],
  cr: [['Venkat Fibre Co. A/c', PC.open.venkat], ['Capital A/c', PC.cap]],
  note: 'Being the assets, the liability and the capital brought forward from the old books',
};
export const PC_TXN = [
  { date: '4 Apr', dr: [['Purchases A/c', PC.purchases]], cr: [['Venkat Fibre Co. A/c', PC.purchases]], note: 'Being goods bought on credit from Venkat Fibre Co.' },
  { date: '9 Apr', dr: [['Cash A/c', PC.cashSales]], cr: [['Sales A/c', PC.cashSales]], note: 'Being goods sold for cash' },
  { date: '15 May', dr: [['Venkat Fibre Co. A/c', PC.paidVenkat]], cr: [['Cash A/c', PC.paidVenkat]], note: 'Being cash paid to Venkat Fibre Co.' },
  { date: '22 Jun', dr: [['Ismail and Sons A/c', PC.creditSale]], cr: [['Sales A/c', PC.creditSale]], note: 'Being goods sold on credit to Ismail and Sons' },
  { date: '30 Jun', dr: [['Wages A/c', PC.wages], ['Rent A/c', PC.rent]], cr: [['Cash A/c', PC.wages + PC.rent]], note: 'Being wages and rent paid in cash' },
  { date: '14 Jul', dr: [['Carriage Inwards A/c', PC.carriage]], cr: [['Cash A/c', PC.carriage]], note: 'Being carriage on purchases paid in cash' },
  { date: '12 Aug', dr: [['Cash A/c', PC.recdIsmail]], cr: [['Ismail and Sons A/c', PC.recdIsmail]], note: 'Being cash received from Ismail and Sons' },
  { date: '3 Oct', dr: [['Furniture A/c', PC.furn]], cr: [['Cash A/c', PC.furnCash], ['Venkat Fibre Co. A/c', PC.furn - PC.furnCash]], note: 'Being furniture bought, part paid in cash and the rest owed to Venkat Fibre Co.' },
  { date: '28 Nov', dr: [['Drawings A/c', PC.drawings]], cr: [['Cash A/c', PC.drawings]], note: 'Being cash withdrawn by the proprietor for personal use' },
  { date: '31 Dec', dr: [['Cash A/c', PC.interest]], cr: [['Interest Received A/c', PC.interest]], note: 'Being interest received in cash' },
  { date: '10 Feb 2028', dr: [['Venkat Fibre Co. A/c', PC.purchRet]], cr: [['Purchases Return A/c', PC.purchRet]], note: 'Being goods returned to Venkat Fibre Co.' },
  { date: '15 Feb 2028', dr: [['Sales Return A/c', PC.salesRet]], cr: [['Ismail and Sons A/c', PC.salesRet]], note: 'Being goods returned by Ismail and Sons' },
];
const OP = openingsFrom(PC_OPENING);
export const PC_LED = postD(PC_TXN, { openings: OP });
const L = PC_LED;
same(L['Cash A/c'].balance, 125000, 'PC cash balance');
same(L['Venkat Fibre Co. A/c'].balance, -85000, 'PC Venkat balance');
same(L['Ismail and Sons A/c'].balance, 50000, 'PC Ismail balance');
same(L['Capital A/c'].balance, -460000, 'PC capital balance');
export const PC_TB = trialFromLedgers(Object.fromEntries(Object.keys(PC_FOLIO).filter((k) => L[k]).map((k) => [k, L[k]])));
same(PC_TB.dr, PC_TB.cr, 'PC trial balance agrees');
// Adjusting entries at 31 March 2028 (introductory depth)
export const PC_DEP = Math.round((PC.open.mach * PC.depPct) / 100);
same(PC_DEP, 30000, 'PC depreciation');
export const PC_ADJ = [
  { date: '31 Mar 2028', dr: [['Wages A/c', PC.wagesDue]], cr: [['Outstanding Wages A/c', PC.wagesDue]], note: 'Being wages due but not paid' },
  { date: '31 Mar 2028', dr: [['Prepaid Rent A/c', PC.rentPrepaid]], cr: [['Rent A/c', PC.rentPrepaid]], note: 'Being rent paid in advance for the next year' },
  { date: '31 Mar 2028', dr: [['Accrued Interest A/c', PC.interestAccrued]], cr: [['Interest Received A/c', PC.interestAccrued]], note: 'Being interest earned but not yet received' },
  { date: '31 Mar 2028', dr: [['Depreciation A/c', PC_DEP]], cr: [['Machinery A/c', PC_DEP]], note: 'Being depreciation on machinery at 10 per cent' },
].map((e) => ({ ...e, jf: 2 }));
const wagesAdj = PC.wages + PC.wagesDue;
const rentAdj = PC.rent - PC.rentPrepaid;
const intAdj = PC.interest + PC.interestAccrued;
export const PC_CLOSE = closingEntries({
  date: '31 Mar 2028',
  tradingDr: [['Stock A/c', PC.open.stock], ['Purchases A/c', PC.purchases], ['Sales Return A/c', PC.salesRet], ['Wages A/c', wagesAdj], ['Carriage Inwards A/c', PC.carriage]],
  tradingCr: [['Sales A/c', PC.cashSales + PC.creditSale], ['Purchases Return A/c', PC.purchRet], ['Closing Stock A/c', PC.closingStock]],
  plDr: [['Rent A/c', rentAdj], ['Depreciation A/c', PC_DEP]],
  plCr: [['Interest Received A/c', intAdj]],
  drawings: ['Drawings A/c', PC.drawings],
});
same(PC_CLOSE.gp, 165000, 'PC gross profit');
same(PC_CLOSE.np, 125000, 'PC net profit');
export const PC_ALL_ENTRIES = [...PC_TXN, ...PC_ADJ, ...PC_CLOSE.entries.map((e) => ({ ...e, jf: 2 }))];
export const PC_ALL = postD(PC_ALL_ENTRIES, { openings: OP });
assertClosed(PC_ALL, ['Stock A/c', 'Purchases A/c', 'Sales A/c', 'Sales Return A/c', 'Purchases Return A/c', 'Wages A/c', 'Carriage Inwards A/c', 'Rent A/c', 'Depreciation A/c', 'Interest Received A/c', 'Trading A/c', 'Profit and Loss A/c', 'Drawings A/c']);
same(PC_ALL['Capital A/c'].balance, -(PC.cap + PC_CLOSE.np - PC.drawings), 'PC closing capital');
same(PC_ALL['Capital A/c'].balance, -549000, 'PC closing capital figure');
same(PC_ALL['Closing Stock A/c'].balance, PC.closingStock, 'PC closing stock balance');
same(PC_ALL['Machinery A/c'].balance, 270000, 'PC machinery after depreciation');
export const PC_BS = balanceSheet({
  liabilities: [['Capital', 549000], ['Venkat Fibre Co.', 85000], ['Outstanding Wages', PC.wagesDue]],
  assets: [['Cash', 125000], ['Ismail and Sons', 50000], ['Closing Stock', PC.closingStock], ['Machinery', 270000], ['Furniture', PC.furn], ['Prepaid Rent', PC.rentPrepaid], ['Accrued Interest', PC.interestAccrued]],
});
// the closing-balance trial balance (ledger balances after all entries) agrees
export const PC_TB2 = trialFromLedgers(PC_ALL);
same(PC_TB2.dr, PC_TB2.cr, 'PC post-closing trial balance agrees');
same(PC_TB2.dr, PC_BS.total, 'post-closing trial balance equals the balance sheet total');
export const FIN = { open: '1 Apr 2027', close: '31 Mar 2028', next: '1 Apr 2028' };

// ================================================================ Case B: Hosur Candle Works (adjusting entries)
export const HC = { stock: 64000, salPaid: 84000, salDue: 7000, insPaid: 14400, insPrepaid: 2400, commRecd: 20000, commAccrued: 5000, rentRecd: 36000, rentAdv: 9000, furn: 120000, depPct: 10 };
HC.dep = (HC.furn * HC.depPct) / 100;
same(HC.dep, 12000, 'HC depreciation');
export const HC_ADJ = [
  { date: '31 Mar 2028', dr: [['Closing Stock A/c', HC.stock]], cr: [['Trading A/c', HC.stock]], note: 'Being closing stock brought into the Trading Account' },
  { date: '31 Mar 2028', dr: [['Salaries A/c', HC.salDue]], cr: [['Outstanding Salaries A/c', HC.salDue]], note: 'Being salaries due for March' },
  { date: '31 Mar 2028', dr: [['Prepaid Insurance A/c', HC.insPrepaid]], cr: [['Insurance A/c', HC.insPrepaid]], note: 'Being insurance paid for the next year' },
  { date: '31 Mar 2028', dr: [['Accrued Commission A/c', HC.commAccrued]], cr: [['Commission Received A/c', HC.commAccrued]], note: 'Being commission earned but not yet received' },
  { date: '31 Mar 2028', dr: [['Rent Received A/c', HC.rentAdv]], cr: [['Rent Received in Advance A/c', HC.rentAdv]], note: 'Being rent received for the next year' },
  { date: '31 Mar 2028', dr: [['Depreciation A/c', HC.dep]], cr: [['Furniture A/c', HC.dep]], note: 'Being depreciation on furniture at 10 per cent' },
];
export const HC_J = jrnl(HC_ADJ, { 'Closing Stock A/c': 1, 'Trading A/c': 2, 'Salaries A/c': 3, 'Outstanding Salaries A/c': 4, 'Prepaid Insurance A/c': 5, 'Insurance A/c': 6, 'Accrued Commission A/c': 7, 'Commission Received A/c': 8, 'Rent Received A/c': 9, 'Rent Received in Advance A/c': 10, 'Depreciation A/c': 11, 'Furniture A/c': 12 });
export const HC_EFFECT = [
  ['Salaries', 'Expense', inr(HC.salPaid), `+ ${inr(HC.salDue)}`, inr(HC.salPaid + HC.salDue), 'Outstanding Salaries: liability'],
  ['Insurance', 'Expense', inr(HC.insPaid), `− ${inr(HC.insPrepaid)}`, inr(HC.insPaid - HC.insPrepaid), 'Prepaid Insurance: asset'],
  ['Commission received', 'Income', inr(HC.commRecd), `+ ${inr(HC.commAccrued)}`, inr(HC.commRecd + HC.commAccrued), 'Accrued Commission: asset'],
  ['Rent received', 'Income', inr(HC.rentRecd), `− ${inr(HC.rentAdv)}`, inr(HC.rentRecd - HC.rentAdv), 'Rent Received in Advance: liability'],
];
export const HC_ADJVAL = { sal: HC.salPaid + HC.salDue, ins: HC.insPaid - HC.insPrepaid, comm: HC.commRecd + HC.commAccrued, rent: HC.rentRecd - HC.rentAdv };
same(HC_ADJVAL.sal, 91000, 'HC salaries adjusted');
same(HC_ADJVAL.ins, 12000, 'HC insurance adjusted');
same(HC_ADJVAL.comm, 25000, 'HC commission adjusted');
same(HC_ADJVAL.rent, 27000, 'HC rent adjusted');

/** Undated ledger account as Markdown with its b/d row (for model answers). */
export const lmd = (l) => acct(l, { close: '', open: '', openingDate: '' });
/** The ledger journal-entry shortcut used in items: { dr: [[a, m]], cr: [[a, m]], note }. */
export const E1 = (dr, cr, note, date) => ({ ...(date ? { date } : {}), dr, cr, note });

/** Ledger account showing only the posted entries (no balance carried down), for accounts that are not balanced yet. */
export function postedOnly(l, { dates = false } = {}) {
  const blank = (t) => /Balance c\/d/.test(t);
  const rows = l.rows.slice(0, -1).map(([dp, da, cp, ca]) => [blank(dp) ? '' : dp, blank(dp) ? '' : da, blank(cp) ? '' : cp, blank(cp) ? '' : ca]).filter((r) => r.some((x) => x));
  void dates;
  const headers = [`Dr: ${l.name}`, '₹', 'Cr: Particulars', '₹'];
  return { headers, rows, md: `**${l.name}**\n\n${mdTable(headers, rows)}` };
}
